describe('Modal Animation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should open modal with animation when trigger button is clicked', () => {
    cy.get('[data-testid="modal-trigger"]').click();

    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal"]').should('have.css', 'opacity', '1');

    cy.get('[data-testid="modal"]').should('have.css', 'transform').and('not.equal', 'none');

    cy.get('[data-testid="modal"]').invoke('css', 'animation-duration').then((duration) => {
      expect(duration).to.match(/^[\d.]+m?s$/);
    });
  });

  it('should close modal with animation when close button is clicked', () => {
    cy.get('[data-testid="modal-trigger"]').click();

    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal-close"]').click();

    cy.get('[data-testid="modal"]').should('not.be.visible');
  });

  it('should handle rapid open and close actions without breaking animation', () => {
    cy.get('[data-testid="modal-trigger"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal-close"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');

    cy.get('[data-testid="modal-trigger"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal"]').should('have.css', 'opacity', '1');
  });

  it('should maintain animation state when modal content is updated', () => {
    cy.get('[data-testid="modal-trigger"]').click();

    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal-content"]').should('contain', 'Modal Title');

    cy.get('[data-testid="modal"]').should('have.css', 'opacity', '1');

    cy.get('[data-testid="modal-update-btn"]').click();

    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').should('have.css', 'opacity', '1');
  });

  it('should not show modal animation when disabled', () => {
    cy.get('[data-testid="modal-trigger"]').click();

    cy.get('[data-testid="disable-animation-toggle"]').click();

    cy.get('[data-testid="modal-close"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');

    cy.get('[data-testid="modal-trigger"]').click();

    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="modal"]').invoke('css', 'animation-duration').then((duration) => {
      expect(duration).to.equal('0s');
    });
  });
});
